css:
.bi{list-style:none;margin:0;padding:0;display:grid;gap:1.5rem 3rem}
.bi__t{margin:0 0 .3em}
.bi__p{margin:0;color:var(--os-color-text-muted)}
.bi__k{display:block;font-family:var(--os-font-heading);font-size:1.1rem;font-weight:500;color:var(--os-color-heading);margin-bottom:.2rem}
@media (min-width:992px){.bi[data-layout=columns]{grid-template-columns:repeat(3,minmax(0,1fr))}}
.bi[data-layout=steps]{gap:1.6rem;margin-top:1rem}
.bi[data-layout=steps] .bi__i{border-top:6px solid #6b8e36;padding-top:1rem}
.bi[data-layout=steps] .bi__i:nth-child(2){border-top-color:#a9a72f}
.bi[data-layout=steps] .bi__i:nth-child(3){border-top-color:#eec02b}
.bi[data-layout=steps] .bi__t{margin-bottom:.25em}
@media (min-width:768px){.bi[data-layout=steps]{grid-template-columns:repeat(3,minmax(0,1fr));gap:2rem;align-items:start}}
.bi[data-layout=rows]{gap:0;margin-top:.4rem}
.bi[data-layout=rows] .bi__i{padding:1.1rem 0;border-top:1px solid rgba(21,38,26,.22);display:grid;gap:.2rem 3rem}
.bi[data-layout=rows] .bi__i:last-child{border-bottom:1px solid rgba(21,38,26,.22)}
.bi[data-layout=rows] .bi__t{font-size:1.35rem;margin:0}
.bi[data-layout=rows] .bi__p{max-width:62ch}
@media (min-width:992px){.bi[data-layout=rows] .bi__i{grid-template-columns:minmax(0,17rem) minmax(0,1fr)}}
